    table: { title: 'This week', ha: 'Day', hb: 'Type', hc: 'Time', rows: [{ a: 'Mon', b: 'Run', c: '32 min' }, { a: 'Wed', b: 'Swim', c: '45 min' }, { a: 'Sat', b: 'Hike', c: '2 h' }] },
