  // what the Expo export draws instead of a part it has no native code for (the same words, a plainer shape)
  function basic(type, p) {
    const rows = (a, f) => ({ type: 'list', props: { title: p.title || '', items: (a || []).map(f) } });
    switch (type) {
      case 'segmented': case 'tags': return { type: 'search', props: { placeholder: '', chips: (p.items || []).slice() } };
      case 'toggles': return { type: 'settings', props: { title: p.title || '', items: (p.items || []).map(i => ({ label: i.label, kind: 'toggle', on: !!i.on })) } };
      case 'slider': case 'progress': return { type: 'stats', props: { tiles: [{ n: p.value || '', label: p.label || '' }] } };
      case 'stepper': return rows([p], i => ({ title: i.label, sub: i.sub || '', icon: 'plus', meta: i.value }));
      case 'rating': return { type: 'stats', props: { tiles: [{ n: p.score, label: p.count }] } };
      case 'steps': return rows(p.items, i => ({ title: i.title, sub: i.sub || '', icon: 'check', meta: '' }));
      case 'stories': return { type: 'search', props: { placeholder: '', chips: (p.items || []).slice() } };
      case 'quote': return { type: 'text', props: { text: `“${p.text}” ${p.who}` } };
      case 'alert': case 'notice': return { type: 'card', props: { title: p.title, sub: p.text, meta: p.app || '', button: p.button || '' } };
      case 'label': return { type: 'header', props: { eyebrow: '', title: p.text, sub: '' } };
      case 'accordion': return rows(p.items, i => ({ title: i.q, sub: i.a, icon: 'chevron', meta: '' }));
      case 'carousel': return { type: 'cards', props: { title: '', items: (p.items || []).map(i => ({ title: i.title, sub: '', illus: i.illus })) } };
      case 'product': return { type: 'card', props: { title: p.title, sub: `${p.sub} · ${p.price}`, meta: p.badge || '', button: p.button } };
      case 'receipt': return rows((p.items || []).concat([{ label: p.total, value: p.amount }]), i => ({ title: i.label, sub: '', icon: 'note', meta: i.value }));
      case 'tracker': return rows(p.items, (s, k) => ({ title: s, sub: k <= (p.on | 0) ? 'Done' : '', icon: k <= (p.on | 0) ? 'check' : 'clock', meta: '' }));
      case 'weather': return { type: 'stats', props: { tiles: [{ n: p.temp, label: p.place }].concat((p.days || []).map(d => ({ n: d.t, label: d.d }))) } };
      case 'countdown': return { type: 'stats', props: { tiles: (p.units || []).map(u => ({ n: u.n, label: u.l })) } };
      case 'rings': return { type: 'stats', props: { tiles: (p.items || []).map(r => ({ n: r.value, label: r.label })) } };
      case 'table': return rows(p.rows, r => ({ title: r.a, sub: r.b, icon: 'list', meta: r.c }));
      case 'contact': return rows([p], i => ({ title: i.name, sub: i.role, icon: 'user', meta: '' }));
      case 'otp': return { type: 'header', props: { eyebrow: '', title: p.title, sub: p.sub } };
      case 'keypad': return { type: 'button', props: { label: p.button || 'Done' } };
      case 'swatches': return { type: 'text', props: { text: (p.items || []).join('  ') } };
      case 'comments': return rows(p.items, c => ({ title: c.who, sub: c.text, icon: 'chat', meta: c.time }));
      case 'wallet': return { type: 'card', props: { title: p.bank, sub: p.number, meta: p.kind, button: '' } };
      case 'coupon': return { type: 'card', props: { title: p.amount, sub: `${p.label} · ${p.code}`, meta: '', button: p.button } };
      case 'poll': return rows(p.items, o => ({ title: o.label, sub: '', icon: 'chart', meta: Math.round(+o.pct || 0) + '%' }));
      case 'voice': return { type: 'player', props: { title: 'Voice note', artist: p.time, illus: 'chat' } };
      case 'video': return { type: 'card', props: { title: p.title, sub: p.sub, meta: p.length, button: 'Play' } };
      case 'kanban': return rows(p.cols, c => ({ title: c.name, sub: (c.cards || []).join(', '), icon: 'grid', meta: String((c.cards || []).length) }));
      case 'hero': return { type: 'card', props: { title: p.title, sub: p.sub, meta: p.eyebrow || '', button: '', illus: p.illus } };
    }
    return null;
  }

